PRAGMA foreign_keys = ON;
CREATE TABLE tenants (id TEXT PRIMARY KEY, created_at TEXT NOT NULL);
CREATE TABLE banks (id TEXT NOT NULL, tenant_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (tenant_id, id), FOREIGN KEY (tenant_id) REFERENCES tenants(id));
CREATE TABLE facts (id TEXT NOT NULL, tenant_id TEXT NOT NULL, bank_id TEXT NOT NULL, revision INTEGER NOT NULL, claim TEXT NOT NULL, confidence REAL NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (tenant_id, bank_id, id, revision), FOREIGN KEY (tenant_id, bank_id) REFERENCES banks(tenant_id, id));
CREATE TABLE evidence (id TEXT NOT NULL, tenant_id TEXT NOT NULL, bank_id TEXT NOT NULL, source TEXT NOT NULL, content TEXT NOT NULL, provenance TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (tenant_id, bank_id, id), FOREIGN KEY (tenant_id, bank_id) REFERENCES banks(tenant_id, id));
CREATE TABLE fact_evidence (fact_tenant_id TEXT NOT NULL, fact_bank_id TEXT NOT NULL, fact_id TEXT NOT NULL, fact_revision INTEGER NOT NULL, evidence_tenant_id TEXT NOT NULL, evidence_bank_id TEXT NOT NULL, evidence_id TEXT NOT NULL, PRIMARY KEY (fact_tenant_id, fact_bank_id, fact_id, fact_revision, evidence_tenant_id, evidence_bank_id, evidence_id), FOREIGN KEY (fact_tenant_id, fact_bank_id, fact_id, fact_revision) REFERENCES facts(tenant_id, bank_id, id, revision), FOREIGN KEY (evidence_tenant_id, evidence_bank_id, evidence_id) REFERENCES evidence(tenant_id, bank_id, id));
CREATE TABLE entities (id TEXT NOT NULL, tenant_id TEXT NOT NULL, bank_id TEXT NOT NULL, label TEXT NOT NULL, PRIMARY KEY (tenant_id, bank_id, id), FOREIGN KEY (tenant_id, bank_id) REFERENCES banks(tenant_id, id));
CREATE TABLE edges (id TEXT NOT NULL, tenant_id TEXT NOT NULL, bank_id TEXT NOT NULL, from_entity TEXT NOT NULL, to_entity TEXT NOT NULL, relation TEXT NOT NULL, PRIMARY KEY (tenant_id, bank_id, id), FOREIGN KEY (tenant_id, bank_id) REFERENCES banks(tenant_id, id));
CREATE TABLE layers (id TEXT NOT NULL, tenant_id TEXT NOT NULL, bank_id TEXT NOT NULL, name TEXT NOT NULL, PRIMARY KEY (tenant_id, bank_id, id), FOREIGN KEY (tenant_id, bank_id) REFERENCES banks(tenant_id, id));
CREATE TABLE events (id TEXT NOT NULL, tenant_id TEXT NOT NULL, bank_id TEXT NOT NULL, type TEXT NOT NULL, payload TEXT NOT NULL, occurred_at TEXT NOT NULL, PRIMARY KEY (tenant_id, bank_id, id), FOREIGN KEY (tenant_id, bank_id) REFERENCES banks(tenant_id, id));
CREATE TABLE outbox (id TEXT NOT NULL, tenant_id TEXT NOT NULL, bank_id TEXT NOT NULL, event_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, status TEXT NOT NULL, PRIMARY KEY (tenant_id, bank_id, id), UNIQUE (tenant_id, idempotency_key), FOREIGN KEY (tenant_id, bank_id) REFERENCES banks(tenant_id, id), FOREIGN KEY (tenant_id, bank_id, event_id) REFERENCES events(tenant_id, bank_id, id));
CREATE TABLE jobs (id TEXT NOT NULL, tenant_id TEXT NOT NULL, bank_id TEXT NOT NULL, status TEXT NOT NULL, PRIMARY KEY (tenant_id, bank_id, id), FOREIGN KEY (tenant_id, bank_id) REFERENCES banks(tenant_id, id));
CREATE TABLE feedback (id TEXT NOT NULL, tenant_id TEXT NOT NULL, bank_id TEXT NOT NULL, value TEXT NOT NULL, PRIMARY KEY (tenant_id, bank_id, id), FOREIGN KEY (tenant_id, bank_id) REFERENCES banks(tenant_id, id));
CREATE TABLE snapshots (id TEXT NOT NULL, tenant_id TEXT NOT NULL, bank_id TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (tenant_id, bank_id, id), FOREIGN KEY (tenant_id, bank_id) REFERENCES banks(tenant_id, id));
CREATE TABLE retrieval_traces (id TEXT NOT NULL, tenant_id TEXT NOT NULL, bank_id TEXT NOT NULL, query TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (tenant_id, bank_id, id), FOREIGN KEY (tenant_id, bank_id) REFERENCES banks(tenant_id, id));
CREATE INDEX facts_scope_idx ON facts (tenant_id, bank_id);
CREATE INDEX evidence_scope_idx ON evidence (tenant_id, bank_id);
CREATE INDEX events_scope_idx ON events (tenant_id, bank_id);
CREATE INDEX outbox_scope_idx ON outbox (tenant_id, bank_id);
